var race=UnityEngine.Object.FindAnyObjectByType<Racer.RaceDirector>();if(Application.isPlaying||race.gameObject.scene.name!="ForestLoopReverse")throw new Exception("Forest edit mode required");
var atlas=JsonUtility.FromJson<InspectRouteAtlas.Atlas>(System.IO.File.ReadAllText("Docs/ForestWaterJump/routes-baseline.json"));var c=atlas.courses.Single(c=>c.scene=="ForestLoopReverse");c.id=race.courseId;
