var original=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Track/RouteAtlas/ForestLoopReverse-property-Ground_560_240.asset");var now=GameObject.Find("Ground_560_240").GetComponent<MeshFilter>().sharedMesh;var a=original.vertices;var v=now.vertices;int ramp=0,pool=0;
for(int i=0;i<a.Length;i++){if(a[i].x!=v[i].x||a[i].z!=v[i].z)throw new Exception("Terrain X/Z changed");if(a[i].y==v[i].y)continue;var p=GameObject.Find("Ground_560_240").transform.TransformPoint(v[i]);if(p.x>430)ramp++;else pool++;}
